window.RP_SESSION={"id":"S-c81214654a2c","messages":[{"id":"RP-0097650","time":"2026-04-02T00:14:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션의 목덜미로 칼날이 다가왔다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097651","time":"2026-04-02T00:15:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"진한 입술선 끝에서 알싸한 비누거품 맛이 느껴졌다. 날카로운 칼날이 빠르게 울대뼈를 훑고 날카로운 손톱으로 긁듯 턱으로 다가갔다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097652","time":"2026-04-02T00:17:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션은 벅벅, 억센 수염을 밀어내고 물 한 양동이를 머리에 끼얹었다. 그리고는 까슬한 수건으로 얼굴을 훔치고 근엄한 표정을 지어보였다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097653","time":"2026-04-02T00:17:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"……너무 허전한데.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-0097654","time":"2026-04-02T00:18:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"멀끔해진 턱을 손가락으로 살살 매만져보았다. 무슨 토르번만한 어린애처럼 보이잖아!","characters":["P-3bbc4a823df9"]},{"id":"RP-0097655","time":"2026-04-02T00:19:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"다른 이들은 절대로 그렇게는 생각하지 않갰지만 션은 인상을 잔뜩 찌푸리면서 욕실에서 나왔다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097656","time":"2026-04-02T00:19:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"흥","characters":[]},{"id":"RP-0097657","time":"2026-04-02T00:21:00+09:00","room":"RP","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"새침하다 토르번","characters":[]},{"id":"RP-0097658","time":"2026-04-02T00:21:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"수건과 면도칼과 함께 걸어나온 션은 뒷목이 영 허전했다. 기다랗게 기른 머리까지 같이 잘랐기 때문이었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097659","time":"2026-04-02T00:22:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"투구 착용이나 전투에 방해되지 않는 짧은 머리에 단정하게 모두 밀어버린 수염. 마치 용사가 되겠다고 설치던 기사 시절, 갓 약관이 된 듯한 이 느낌.","characters":["P-3bbc4a823df9"]},{"id":"RP-0097660","time":"2026-04-02T00:23:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그가 후대에 이런 생각과 행동거지를 영포티라고 부른다는 사실을 영영 모르는 것이 다행이었다. 아니면 한달 정도 스스로 수치스러워 했을 테니까!","characters":["P-3bbc4a823df9"]},{"id":"RP-0097661","time":"2026-04-02T00:23:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-0097662","time":"2026-04-02T00:23:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
